565:     for (i = 0; ((size_t)i < base_path_len) && (path[i]) && (base_path[i] == path[i]); i++) {
566:         path_start = path + i + 1;
567:     }
568:     log_debug("search_dir: path is '%s', base_path is '%s', path_start is '%s'", path, base_path, path_start);
569: 
570:     scandir_baton.ig = ig;
571:     scandir_baton.base_path = base_path;
572:     scandir_baton.base_path_len = base_path_len;
573:     scandir_baton.path_start = path_start;
