586:                 }
587:                 /* If we're only searching one file and --only-matching is specified, disable line numbers too. */
588:                 if (opts.only_matching && opts.print_path == PATH_PRINT_NOTHING) {
589:                     opts.print_line_numbers = FALSE;
590:                 }
591:             }
592:             search_file(path);
593:         } else {
594:             log_err("Error opening directory %s: %s", path, strerror(errno));
595:         }
596:         goto search_dir_cleanup;
597:     }
598: 
599:     int offset_vector[3];
600:     int rc = 0;
601:     work_queue_t *queue_item;
602: 
603:     for (i = 0; i < results; i++) {
604:         queue_item = NULL;
605:         dir = dir_list[i];
606:         ag_asprintf(&dir_full_path, "%s/%s", path, dir->d_name);
607: #ifndef _WIN32
608:         if (opts.one_dev) {
609:             struct stat s;
610:             if (lstat(dir_full_path, &s) != 0) {
611:                 log_err("Failed to get device information for %s. Skipping...", dir->d_name);
612:                 goto cleanup;
613:             }
614:             if (s.st_dev != original_dev) {
615:                 log_debug("File %s crosses a device boundary (is probably a mount point.) Skipping...", dir->d_name);
616:                 goto cleanup;
617:             }
618:         }
619: #endif
