230:         /* Drain output buffer first */
231:         while (CNEXT_OUT(cookie) >
232:                &cookie->outbuf[cookie->outbuf_start]) {
233:             size_t left = CNEXT_OUT(cookie) -
234:                           &cookie->outbuf[cookie->outbuf_start];
235:             size_t ignoreskip = min(ignorebytes, left);
236:             size_t toread;
237: 
238:             if (ignoreskip > 0) {
239:                 ignorebytes -= ignoreskip;
240:                 left -= ignoreskip;
241:                 cookie->outbuf_start += ignoreskip;
242:                 cookie->decode_offset += ignoreskip;
243:             }
244: 
245:             // Ran out of output before we seek()ed up.
246:             if (ignorebytes > 0)
247:                 break;
248: 
249:             toread = min(left, size);
250:             memcpy(buf, &cookie->outbuf[cookie->outbuf_start],
251:                    toread);
252: 
253:             buf += toread;
254:             size -= toread;
255:             left -= toread;
256:             cookie->outbuf_start += toread;
257:             cookie->decode_offset += toread;
258:             cookie->logic_offset += toread;
259:             total += toread;
260: 
261:             if (size == 0)
262:                 break;
263:         }
264: 
265:         if (size == 0)
266:             break;
267: 
268:         /*
269: 		 * If we have not satisfied read, the output buffer must be
270: 		 * empty.
271: 		 */
272:         assert(cookie->stream.gz.next_out ==
273:                &cookie->outbuf[cookie->outbuf_start]);
