275:         if ((cookie->ctype == AG_XZ && lzret == LZMA_STREAM_END) ||
276:             (cookie->ctype == AG_GZIP && ret == Z_STREAM_END)) {
277:             cookie->eof = true;
278:             break;
279:         }
280: 
281:         /* Read more input if empty */
282:         if (CAVAIL_IN(cookie) == 0) {
283:             nb = fread(cookie->inbuf, 1, sizeof cookie->inbuf,
284:                        cookie->in);
285:             if (ferror(cookie->in)) {
286:                 warn("error read core");
287:                 exit(1);
288:             }
289:             if (nb == 0 && feof(cookie->in)) {
290:                 warn("truncated file");
291:                 exit(1);
292:             }
293:             if (cookie->ctype == AG_XZ) {
294:                 cookie->stream.lzma.avail_in = nb;
295:                 cookie->stream.lzma.next_in = cookie->inbuf;
296:             } else {
297:                 cookie->stream.gz.avail_in = nb;
298:                 cookie->stream.gz.next_in = cookie->inbuf;
299:             }
300:         }
301: 
302:         /* Reset stream state to beginning of output buffer */
303:         if (cookie->ctype == AG_XZ) {
304:             cookie->stream.lzma.next_out = cookie->outbuf;
305:             cookie->stream.lzma.avail_out = sizeof cookie->outbuf;
306:         } else {
307:             cookie->stream.gz.next_out = cookie->outbuf;
308:             cookie->stream.gz.avail_out = sizeof cookie->outbuf;
309:         }
310:         cookie->outbuf_start = 0;
